export function screenBars(scores,l='en',interactive=false){return `<div class="mh-screen-bars">${[['anxiety',say(l,'Worry & anxiety','चिंता और घबराहट'),'#598caa'],['mood',say(l,'Low mood & interest','उदासी और रुचि'),'#9b88ac']].map(([key,label,color])=>`<${interactive?'button':'div'} class="mh-screen-row" ${interactive?`data-screen-detail="${key}" aria-pressed="${key==='anxiety'}"`:''}><span class="mh-bar-label"><strong>${label}</strong><b>${scores[key]}<small> / 6</small></b></span><span class="mh-bar-track"><i style="width:${scores[key]/6*100}%;background:${color}"></i><span class="mh-threshold"></span></span><span class="mh-bar-ends"><span>0</span><span>${say(l,'Follow-up threshold: 3','आगे बातचीत का संकेत: 3')}</span><span>6</span></span></${interactive?'button':'div'}>`).join('')}</div>`;}
export function responseBars(answers,l='en'){
 l=displayLanguage(l);return `<div class="mh-responses">${answers.slice(0,4).map((value,i)=>`<div><div><span>${symptoms(l)[i]}</span><strong>${frequency[l][value]}</strong></div><div class="mh-response-track"><span style="width:${value/3*100}%"></span></div></div>`).join('')}</div>`;}
export function historyChart(records,l='en',sample=false,historyLanguage=l){
 const history=sample?[{scores:{total:8},createdAt:'2026-01-01',id:'sample1'},{scores:{total:5},createdAt:'2026-01-15',id:'sample2'},{scores:{total:6},createdAt:'2026-01-29',id:'sample3'}]:compatibleHistory(records,historyLanguage);
 if(!history.length)return `<div class="mh-empty">${say(l,'Your first saved check-in will start your timeline.','आपका पहला सेव किया check-in इस यात्रा की शुरुआत होगा।')}</div>`;
 const first=Date.parse(history[0].createdAt),span=Date.parse(history.at(-1).createdAt)-first;
 const point=(r)=>[history.length===1?220:48+(Date.parse(r.createdAt)-first)/span*344,215-r.scores.total/12*170];
 return `<div class="mh-timeline"><svg viewBox="0 0 440 270" role="img" aria-label="${esc(say(l,sample?'Illustrative PHQ-4 totals across three fictional check-ins: 8, 5, 6.':'Your saved PHQ-4 totals over time. Exact values are listed below.',sample?'तीन काल्पनिक check-ins के PHQ-4 totals: 8, 5, 6।':'आपके सेव किए PHQ-4 totals। नीचे सभी मान दिए हैं।'))}">${[0,3,6,9,12].map(n=>`<path d="M48 ${215-n/12*170}H392" stroke="#dfe7ec" stroke-dasharray="3 5"/><text x="31" y="${220-n/12*170}" text-anchor="end">${n}</text>`).join('')}${history.length>1?`<polyline class="mh-chart-draw" points="${history.map(r=>point(r).join(',')).join(' ')}" fill="none" stroke="#538b99" stroke-width="3"/>`:''}${history.map((r,i)=>{const [x,y]=point(r);return `<circle cx="${x}" cy="${y}" r="6" fill="#538b99" stroke="white" stroke-width="2"/><text x="${x}" y="${y-14}" text-anchor="middle">${r.scores.total}</text><text x="${x}" y="246" text-anchor="middle">${sample?`${i+1}`:i===0||i===history.length-1?new Date(r.createdAt).toLocaleDateString(l,{day:'numeric',month:'short'}):''}</text>`;}).join('')}</svg><p class="mh-chart-note">${say(l,sample?'Example only · Three fictional check-ins':history.length===1?'One check-in is a starting point, not a trend.':'PHQ-4 total / 12 · Lower means fewer reported symptoms.',sample?'सिर्फ़ उदाहरण · तीन काल्पनिक check-ins':history.length===1?'एक check-in शुरुआत है, trend नहीं।':'PHQ-4 कुल / 12 · कम अंक यानी कम बताए गए लक्षण।')}</p>${!sample?`<div class="mh-history-points" role="group" aria-label="${say(l,'Read a saved check-in','सेव किया check-in देखें')}">${history.map(r=>`<button data-history-point="${esc(r.id)}">${new Date(r.createdAt).toLocaleDateString(l,{day:'numeric',month:'short'})} <strong>${r.scores.total}/12</strong></button>`).join('')}</div>`:''}</div>`;
}
